mapper.select:
/** slave-generalcustomer-mapper.slaveGetGeneralCustomerListByParam (일반회원관리 목록 조회) */ SELECT A.user_id, A.login_id AS login_id, A.user_name AS user_name, A.email AS email, A.sbscrb_se_code, (SELECT label FROM OP_COMMON_CODE C WHERE C.code_type = 'SBSCRB_SE' AND C.use_yn = 'Y' AND C.language = 'ko' AND C.id = A.SBSCRB_SE_CODE) AS sbscrb_se_nm, CASE WHEN IFNULL(A.created_date, '') != '' THEN DATE_FORMAT(A.created_date, '%Y-%m-%d') ELSE '' END AS created_date, CASE WHEN IFNULL(A.login_date, '') != '' THEN DATE_FORMAT(A.login_date, '%Y-%m-%d %H:%i:%s') ELSE '' END AS login_date, A.post AS post, A.address AS address, A.address_detail AS address_detail, A.receive_email, A.phone_number AS phone_number, (SELECT SUM(cntr_amt) FROM G_CNTR WHERE user_id = A.user_id AND sttemnt_pay_de IS NOT NULL AND delete_at = 'N' AND cntr_sttus_code = '200') AS total_cntr_amt, ( A.TOTAL_CNTR_POINT - A.TOTAL_CNTR_USE_POINT) as total_cntr_blce_point FROM (
SELECT U.user_id, U.login_id, U.user_name, U.email, U.sbscrb_se_code, U.created_date, U.login_date, UD.post, UD.address, UD.address_detail, UD.receive_email, UD.phone_number, ( SELECT IFNULL(SUM(A.CNTR_USE_POINT), 0) FROM G_CNTR_USE_POINT A LEFT OUTER JOIN G_CNTR B ON A.CNTR_SN = B.CNTR_SN AND B.CNTR_STTUS_CODE = '200' WHERE A.USER_ID = U.USER_ID AND A.USE_SE_CODE = '1') as TOTAL_CNTR_USE_POINT, ( SELECT SUM(A.CNTR_POINT) FROM G_CNTR A WHERE A.USER_ID = U.USER_ID AND A.CNTR_STTUS_CODE = '200' AND A.STTEMNT_PAY_DE IS NOT NULL ) as TOTAL_CNTR_POINT FROM OP_USER U INNER JOIN OP_USER_DETAIL UD ON UD.user_id = U.user_id AND UD.use_flag = 'Y' WHERE U.status_code = 9
ORDER BY U.created_date DESC
) A

/** slave-generalcustomer-mapper.getGeneralCustomerPointCountByParam (포인트 내역 목록 갯수 조회) */ SELECT COUNT(*) FROM ( SELECT CNTR_DE, CNTR_AMT, CNTR_POINT, CNTR_LOCGOV_CODE, '' AS ORDER_CODE, '' AS CNTR_USE_POINT, ( SELECT SUM(CNTR_POINT) FROM G_CNTR A WHERE A.FRST_REGIST_PNTTM <= GC.FRST_REGIST_PNTTM AND A.CNTR_LOCGOV_CODE = GC.CNTR_LOCGOV_CODE AND A.USER_ID = GC.USER_ID AND A.STTEMNT_PAY_DE IS NOT NULL AND A.DELETE_AT = 'N' AND A.CNTR_STTUS_CODE = '200' ) AS CURRENT_CNTR_POINT, ( SELECT IFNULL(SUM(CNTR_USE_POINT),0) FROM G_CNTR_USE_POINT A WHERE A.FRST_REGIST_PNTTM <= GC.FRST_REGIST_PNTTM AND A.CNTR_LOCGOV_CODE = GC.CNTR_LOCGOV_CODE AND A.USER_ID = GC.USER_ID ) AS CURRENT_CNTR_USE_POINT, FRST_REGIST_PNTTM, '' AS USE_SN FROM G_CNTR GC WHERE GC.USER_ID = #{userId} AND GC.STTEMNT_PAY_DE IS NOT NULL AND GC.DELETE_AT = 'N' AND GC.CNTR_STTUS_CODE = '200'
UNION ALL
SELECT POINT_USE_DE AS CNTR_DE, '' AS CNTR_AMT, '' AS CNTR_POINT, CNTR_LOCGOV_CODE, ORDER_CODE, CNTR_USE_POINT, ( SELECT SUM(CNTR_POINT) FROM G_CNTR A WHERE A.FRST_REGIST_PNTTM <= GC.FRST_REGIST_PNTTM AND A.CNTR_LOCGOV_CODE = GC.CNTR_LOCGOV_CODE AND A.USER_ID = GC.USER_ID AND A.STTEMNT_PAY_DE IS NOT NULL AND A.DELETE_AT = 'N' AND A.CNTR_STTUS_CODE = '200' ) AS CURRENT_CNTR_POINT, ( SELECT IFNULL(SUM(CNTR_USE_POINT),0) FROM G_CNTR_USE_POINT A WHERE A.FRST_REGIST_PNTTM <= GC.FRST_REGIST_PNTTM AND A.CNTR_LOCGOV_CODE = GC.CNTR_LOCGOV_CODE AND A.USER_ID = GC.USER_ID ) AS CURRENT_CNTR_USE_POINT, FRST_REGIST_PNTTM, USE_SN FROM G_CNTR_USE_POINT GC WHERE GC.USER_ID = #{userId} ) A

/** slave-generalcustomer-mapper.getPasswordByUserId (로그인 사용자 비밀번호 조회) */
SELECT M.PASSWORD
FROM OP_MANAGER M
WHERE M.USER_ID = #{userId}
LIMIT 1

/** slave-generalcustomer-mapper.getSecedeGeneralCustomerParent (회원 탈퇴 시 부모 인증 처리) */
SELECT COUNT(*) FROM OP_USER_PARENT
WHERE	USER_ID = #{userId}
